INSERT OR REPLACE INTO ziyarat_routes (id,slug,city,country,title,subtitle,transport_mode,status,created_at,updated_at) VALUES ('makkah-main','makkah-ziyarat','Makkah','Saudi Arabia','Makkah Ziyarat','Sacred and historic places around Makkah','car','published','2026-09-11T16:30:00.000Z','2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'jabal-thawr', 'makkah-main', 'jabal-thawr', 'Jabal Thawr / Cave of Thawr', 'جبل ثور / غار ثور', 'mountain', 'A historic mountain south of Makkah, home to the cave associated with the Prophet’s ﷺ Hijrah to Madinah.', 'Jabal Thawr is a mountain south of Makkah. Near its summit is the Cave of Thawr, where the Prophet Muhammad ﷺ and Abu Bakr رضي الله عنه took refuge for three nights during the Hijrah before continuing toward Madinah. The Qur’an refers to the event of the two companions in the cave in Surah At-Tawbah 9:40. The saved map point marks the cave itself; reaching it requires a demanding mountain climb and should not be treated as an ordinary short walk.', '["The Cave of Thawr is connected with the Hijrah from Makkah to Madinah.","The Prophet ﷺ and Abu Bakr رضي الله عنه remained in the cave for three nights.","The Qur’an mentions the event of the two companions in the cave in Surah At-Tawbah 9:40."]', 'Historic stop. The map pin marks the cave, but the ascent is steep and physically demanding. Follow the live guide and current local access guidance; viewing the mountain does not require climbing to the cave.', 'stop', 30, 21.3768194, 39.8500389, 'Jabal Thawr, Makkah, Saudi Arabia', 'Cave of Thawr · exact point', 1, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

