INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('jabal-thawr', 'ru', 'Гора Савр / пещера Савр', 'Историческая гора к югу от Мекки с пещерой, связанной с хиджрой Пророка ﷺ в Медину.', 'Джабаль Савр — гора к югу от Мекки. Недалеко от её вершины находится пещера Савр, где Пророк Мухаммад ﷺ и Абу Бакр رضي الله عنه укрывались три ночи во время хиджры, прежде чем продолжить путь в Медину. В суре «Ат-Тауба», 9:40, упоминается событие двух спутников в пещере. Точка на карте указывает именно на пещеру; подъём к ней сложный и не должен восприниматься как обычная короткая прогулка.', '["Пещера Савр связана с хиджрой из Мекки в Медину.","Пророк ﷺ и Абу Бакр رضي الله عنه провели в пещере три ночи.","Событие двух спутников в пещере упоминается в суре «Ат-Тауба», 9:40."]', 'Историческая остановка. Метка показывает саму пещеру, однако подъём крутой и физически сложный. Следуйте указаниям живого гида и действующим местным правилам; для осмотра горы необязательно подниматься к пещере.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jabal-thawr', 'uz', 'Savr tog‘i / Savr g‘ori', 'Makka janubidagi tarixiy tog‘ va Payg‘ambarimiz ﷺning Madinaga hijrati bilan bog‘liq g‘or.', 'Jabal Savr — Makka janubidagi tog‘. Uning cho‘qqisiga yaqin joyda Savr g‘ori bor. Hijrat vaqtida Payg‘ambarimiz Muhammad ﷺ va Abu Bakr رضي الله عنه Madina tomon yo‘lni davom ettirishdan oldin bu g‘orda uch kecha panoh topganlar. Tavba surasining 9:40-oyatida g‘ordagi ikki hamroh voqeasi eslatiladi. Xarita belgisi aynan g‘orni ko‘rsatadi; unga chiqish tik va jismonan og‘ir bo‘lib, oddiy qisqa sayr sifatida qaralmasligi kerak.', '["Savr g‘ori Makkadan Madinaga hijrat bilan bog‘liq.","Payg‘ambarimiz ﷺ va Abu Bakr رضي الله عنه g‘orda uch kecha qolganlar.","G‘ordagi ikki hamroh voqeasi Tavba surasi 9:40-oyatida eslatiladi."]', 'Tarixiy to‘xtash. Xarita g‘orning o‘zini ko‘rsatadi, ammo ko‘tarilish tik va jismonan qiyin. Jonli gid va amaldagi mahalliy ko‘rsatmalarga rioya qiling; tog‘ni ko‘rish uchun g‘orgacha chiqish shart emas.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jabal-thawr', 'uz-cyrl', 'Савр тоғи / Савр ғори', 'Макка жанубидаги тарихий тоғ ва Пайғамбаримиз ﷺнинг Мадинага ҳижрати билан боғлиқ ғор.', 'Жабал Савр — Макка жанубидаги тоғ. Унинг чўққисига яқин жойда Савр ғори бор. Ҳижрат вақтида Пайғамбаримиз Муҳаммад ﷺ ва Абу Бакр رضي الله عنه Мадина томон йўлни давом эттиришдан олдин бу ғорда уч кеча паноҳ топганлар. Тавба сурасининг 9:40-оятида ғордаги икки ҳамроҳ воқеаси эслатилади. Харита белгиси айнан ғорни кўрсатади; унга чиқиш тик ва жисмонан оғир бўлиб, оддий қисқа сайр сифатида қаралмаслиги керак.', '["Савр ғори Маккадан Мадинага ҳижрат билан боғлиқ.","Пайғамбаримиз ﷺ ва Абу Бакр رضي الله عنه ғорда уч кеча қолганлар.","Ғордаги икки ҳамроҳ воқеаси Тавба сураси 9:40-оятида эслатилади."]', 'Тарихий тўхташ. Харита ғорнинг ўзини кўрсатади, аммо кўтарилиш тик ва жисмонан қийин. Жонли гид ва амалдаги маҳаллий кўрсатмаларга риоя қилинг; тоғни кўриш учун ғоргача чиқиш шарт эмас.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jabal-thawr', 'en', 'Jabal Thawr / Cave of Thawr', 'A historic mountain south of Makkah, home to the cave associated with the Prophet’s ﷺ Hijrah to Madinah.', 'Jabal Thawr is a mountain south of Makkah. Near its summit is the Cave of Thawr, where the Prophet Muhammad ﷺ and Abu Bakr رضي الله عنه took refuge for three nights during the Hijrah before continuing toward Madinah. The Qur’an refers to the event of the two companions in the cave in Surah At-Tawbah 9:40. The saved map point marks the cave itself; reaching it requires a demanding mountain climb and should not be treated as an ordinary short walk.', '["The Cave of Thawr is connected with the Hijrah from Makkah to Madinah.","The Prophet ﷺ and Abu Bakr رضي الله عنه remained in the cave for three nights.","The Qur’an mentions the event of the two companions in the cave in Surah At-Tawbah 9:40."]', 'Historic stop. The map pin marks the cave, but the ascent is steep and physically demanding. Follow the live guide and current local access guidance; viewing the mountain does not require climbing to the cave.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'arafat-jabal-rahmah', 'makkah-main', 'arafat-jabal-rahmah', 'Arafat — Jabal al-Rahmah', 'عرفات — جبل الرحمة', 'mountain', 'The best-known hill on the Plain of Arafat, one of the central sacred areas of Hajj.', 'Jabal al-Rahmah, or the Mount of Mercy, is the best-known hill on the Plain of Arafat east of Makkah. Arafat is the central location of the Hajj standing on the ninth of Dhu al-Hijjah. The hill is a landmark within Arafat, but standing on or climbing the hill is not a requirement of Hajj; the standing takes place throughout the defined area of Arafat.', '["Jabal al-Rahmah is one of the most recognizable landmarks of Arafat.","The standing at Arafat on 9 Dhu al-Hijjah is a central rite of Hajj.","Climbing Jabal al-Rahmah is not required for the standing at Arafat."]', 'Sacred-site stop. Respect current crowd-control and access instructions. During Hajj, movement is highly regulated; outside Hajj the live guide should determine the practical stopping point.', 'stop', 30, 21.3548311, 39.9838861, 'Jabal al-Rahmah, Arafat, Makkah, Saudi Arabia', 'Jabal al-Rahmah · exact point', 2, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

