INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('arafat-jabal-rahmah', 'ru', 'Арафат — Джабаль ар-Рахма', 'Самая известная возвышенность на равнине Арафат — одной из центральных священных территорий хаджа.', 'Джабаль ар-Рахма, или Гора Милости, — самая известная возвышенность на равнине Арафат к востоку от Мекки. Арафат является местом главного стояния хаджа 9 Зуль-хиджа. Сама гора служит ориентиром внутри Арафата, однако стоять именно на ней или подниматься на неё для хаджа не требуется: стояние действительно на всей установленной территории Арафата.', '["Джабаль ар-Рахма — один из самых узнаваемых ориентиров Арафата.","Стояние на Арафате 9 Зуль-хиджа — центральный обряд хаджа.","Подъём на Джабаль ар-Рахма не является условием стояния на Арафате."]', 'Остановка на священной территории. Соблюдайте действующие правила доступа и управления потоками людей. Во время хаджа движение строго регулируется; вне хаджа практическую точку остановки определяет живой гид.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('arafat-jabal-rahmah', 'uz', 'Arafot — Jabal ar-Rahma', 'Arafot vodiysidagi eng mashhur tepalik va Hajning markaziy muqaddas hududlaridan biri.', 'Jabal ar-Rahma, ya’ni Rahmat tog‘i, Makka sharqidagi Arafot vodiysining eng mashhur tepaligidir. Arafot 9 Zulhijja kuni Hajdagi asosiy wuquf joyidir. Tog‘ Arafot ichidagi mashhur belgi, ammo Haj uchun aynan tog‘ ustida turish yoki unga chiqish shart emas; wuquf Arafotning belgilangan hududi bo‘ylab amalga oshadi.', '["Jabal ar-Rahma Arafotning eng taniqli belgilaridan biridir.","9 Zulhijja kuni Arafotda turish Hajning markaziy ruknlaridan biridir.","Jabal ar-Rahmaga chiqish Arafotdagi wuquf uchun shart emas."]', 'Muqaddas hududdagi to‘xtash. Amaldagi kirish va odamlar oqimini boshqarish ko‘rsatmalariga rioya qiling. Haj vaqtida harakat qat’iy tartibga solinadi; boshqa paytda amaliy to‘xtash nuqtasini jonli gid belgilaydi.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('arafat-jabal-rahmah', 'uz-cyrl', 'Арафот — Жабал ар-Раҳма', 'Арафот водийсидаги энг машҳур тепалик ва Ҳажнинг марказий муқаддас ҳудудларидан бири.', 'Жабал ар-Раҳма, яъни Раҳмат тоғи, Макка шарқидаги Арафот водийсининг энг машҳур тепалигидир. Арафот 9 Зулҳижжа куни Ҳаждаги асосий вуқуф жойидир. Тоғ Арафот ичидаги машҳур белги, аммо Ҳаж учун айнан тоғ устида туриш ёки унга чиқиш шарт эмас; вуқуф Арафотнинг белгиланган ҳудуди бўйлаб амалга ошади.', '["Жабал ар-Раҳма Арафотнинг энг таниқли белгиларидан биридир.","9 Зулҳижжа куни Арафотда туриш Ҳажнинг марказий рукнларидан биридир.","Жабал ар-Раҳмага чиқиш Арафотдаги вуқуф учун шарт эмас."]', 'Муқаддас ҳудуддаги тўхташ. Амалдаги кириш ва одамлар оқимини бошқариш кўрсатмаларига риоя қилинг. Ҳаж вақтида ҳаракат қатъий тартибга солинади; бошқа пайтда амалий тўхташ нуқтасини жонли гид белгилайди.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('arafat-jabal-rahmah', 'en', 'Arafat — Jabal al-Rahmah', 'The best-known hill on the Plain of Arafat, one of the central sacred areas of Hajj.', 'Jabal al-Rahmah, or the Mount of Mercy, is the best-known hill on the Plain of Arafat east of Makkah. Arafat is the central location of the Hajj standing on the ninth of Dhu al-Hijjah. The hill is a landmark within Arafat, but standing on or climbing the hill is not a requirement of Hajj; the standing takes place throughout the defined area of Arafat.', '["Jabal al-Rahmah is one of the most recognizable landmarks of Arafat.","The standing at Arafat on 9 Dhu al-Hijjah is a central rite of Hajj.","Climbing Jabal al-Rahmah is not required for the standing at Arafat."]', 'Sacred-site stop. Respect current crowd-control and access instructions. During Hajj, movement is highly regulated; outside Hajj the live guide should determine the practical stopping point.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'muzdalifah', 'makkah-main', 'muzdalifah-al-mashar-al-haram', 'Muzdalifah — Al-Mash’ar al-Haram', 'مزدلفة — المشعر الحرام', 'historical', 'The sacred Hajj site between Arafat and Mina, anchored on the map by Al-Mash’ar al-Haram Mosque.', 'Muzdalifah is the sacred area between Arafat and Mina. During Hajj, pilgrims arrive here after leaving Arafat, combine the Maghrib and Isha prayers, spend the night and then continue toward Mina. Al-Mash’ar al-Haram Mosque is a clear landmark within Muzdalifah and provides a precise map point for this route.', '["Muzdalifah lies between Arafat and Mina.","Pilgrims come here after the standing at Arafat and continue to Mina afterward.","Al-Mash’ar al-Haram Mosque is one of the principal landmarks within Muzdalifah."]', 'Sacred-site stop. Hajj-season access and traffic patterns are tightly controlled. The exact pin is the Al-Mash’ar al-Haram Mosque; follow the live guide and official directions for the usable meeting or stopping area.', 'stop', 25, 21.3862222, 39.9124722, 'Al-Mash’ar al-Haram Mosque, Muzdalifah, Makkah, Saudi Arabia', 'Al-Mash’ar al-Haram · Muzdalifah', 3, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

