INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('muzdalifah', 'ru', 'Муздалифа — Аль-Маш‘ар аль-Харам', 'Священная территория хаджа между Арафатом и Миной; точка на карте привязана к мечети Аль-Маш‘ар аль-Харам.', 'Муздалифа — священная территория между Арафатом и Миной. Во время хаджа паломники прибывают сюда после Арафата, совмещают намазы Магриб и Иша, проводят здесь ночь и затем направляются в Мину. Мечеть Аль-Маш‘ар аль-Харам является понятным ориентиром внутри Муздалифы и используется как точная точка этого маршрута на карте.', '["Муздалифа находится между Арафатом и Миной.","Паломники прибывают сюда после стояния на Арафате и затем направляются в Мину.","Мечеть Аль-Маш‘ар аль-Харам — один из главных ориентиров Муздалифы."]', 'Остановка на священной территории. В сезон хаджа доступ и движение транспорта строго регулируются. Точная метка — мечеть Аль-Маш‘ар аль-Харам; следуйте указаниям живого гида и официальным схемам движения.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('muzdalifah', 'uz', 'Muzdalifa — Al-Mash’ar al-Haram', 'Arafot bilan Mina orasidagi muqaddas Haj hududi; xarita nuqtasi Al-Mash’ar al-Haram masjidiga bog‘langan.', 'Muzdalifa — Arafot va Mina orasidagi muqaddas hudud. Hajda ziyoratchilar Arafotdan keyin bu yerga keladilar, Shom va Xufton namozlarini jam qiladilar, tunab qoladilar va keyin Mina tomon yo‘l oladilar. Al-Mash’ar al-Haram masjidi Muzdalifadagi aniq va tanish orientir bo‘lib, iumrah xaritasida shu nuqta saqlanadi.', '["Muzdalifa Arafot bilan Mina orasida joylashgan.","Ziyoratchilar Arafotdagi wuqufdan keyin bu yerga kelib, so‘ng Mina tomon yo‘l oladilar.","Al-Mash’ar al-Haram masjidi Muzdalifadagi asosiy orientirlardan biridir."]', 'Muqaddas hududdagi to‘xtash. Haj mavsumida kirish va transport harakati qat’iy boshqariladi. Aniq belgi Al-Mash’ar al-Haram masjididir; jonli gid va rasmiy harakat ko‘rsatmalariga rioya qiling.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('muzdalifah', 'uz-cyrl', 'Муздалифа — Ал-Машъар ал-Ҳарам', 'Арафот билан Мина орасидаги муқаддас Ҳаж ҳудуди; харита нуқтаси Ал-Машъар ал-Ҳарам масжидига боғланган.', 'Муздалифа — Арафот ва Мина орасидаги муқаддас ҳудуд. Ҳажда зиёратчилар Арафотдан кейин бу ерга келадилар, Шом ва Хуфтон намозларини жам қиладилар, тунаб қоладилар ва кейин Мина томон йўл оладилар. Ал-Машъар ал-Ҳарам масжиди Муздалифадаги аниқ ва таниш ориентир бўлиб, iumrah харитасида шу нуқта сақланади.', '["Муздалифа Арафот билан Мина орасида жойлашган.","Зиёратчилар Арафотдаги вуқуфдан кейин бу ерга келиб, сўнг Мина томон йўл оладилар.","Ал-Машъар ал-Ҳарам масжиди Муздалифадаги асосий ориентирлардан биридир."]', 'Муқаддас ҳудуддаги тўхташ. Ҳаж мавсумида кириш ва транспорт ҳаракати қатъий бошқарилади. Аниқ белги Ал-Машъар ал-Ҳарам масжидидир; жонли гид ва расмий ҳаракат кўрсатмаларига риоя қилинг.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('muzdalifah', 'en', 'Muzdalifah — Al-Mash’ar al-Haram', 'The sacred Hajj site between Arafat and Mina, anchored on the map by Al-Mash’ar al-Haram Mosque.', 'Muzdalifah is the sacred area between Arafat and Mina. During Hajj, pilgrims arrive here after leaving Arafat, combine the Maghrib and Isha prayers, spend the night and then continue toward Mina. Al-Mash’ar al-Haram Mosque is a clear landmark within Muzdalifah and provides a precise map point for this route.', '["Muzdalifah lies between Arafat and Mina.","Pilgrims come here after the standing at Arafat and continue to Mina afterward.","Al-Mash’ar al-Haram Mosque is one of the principal landmarks within Muzdalifah."]', 'Sacred-site stop. Hajj-season access and traffic patterns are tightly controlled. The exact pin is the Al-Mash’ar al-Haram Mosque; follow the live guide and official directions for the usable meeting or stopping area.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'mina-holy-site', 'makkah-main', 'mina-holy-site', 'Mina Holy Site', 'مشعر منى', 'historical', 'The major Hajj valley closest to the Grand Mosque, famous for its vast seasonal tent city.', 'Mina is a sacred Hajj site in a valley east of the Grand Mosque. Pilgrims stay here on the Day of Tarwiyah and return during the Days of Tashriq. The area contains the Jamarat Complex and Al-Khayf Mosque and becomes one of the largest temporary accommodation areas in the world during Hajj, with extensive fire-resistant tent infrastructure.', '["Mina is the closest of the main Hajj holy sites to Al-Masjid al-Haram.","It is widely known for its enormous seasonal tent city.","The Jamarat Complex and Al-Khayf Mosque are located within Mina."]', 'Area stop. Mina is very large; this marker is a central route reference, while the live guide should use the group’s current camp, road and access plan. Hajj-season entry and traffic controls can change.', 'stop', 30, 21.4133333, 39.8933333, 'Mina Holy Site, Makkah, Saudi Arabia', 'Mina Holy Site · central point', 4, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

