INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('mina-holy-site', 'ru', 'Мина', 'Крупная долина хаджа, ближайшая к Заповедной мечети и известная огромным сезонным городом палаток.', 'Мина — священная территория хаджа в долине к востоку от Аль-Масджид аль-Харам. Паломники находятся здесь в День Тарвия и возвращаются в дни Ташрика. На территории расположены комплекс Джамарат и мечеть Аль-Хайф, а во время хаджа Мина превращается в один из крупнейших временных городов размещения с масштабной системой огнестойких палаток.', '["Мина — ближайшая к Аль-Масджид аль-Харам из основных священных территорий хаджа.","Она известна огромным сезонным палаточным городом.","В Мине находятся комплекс Джамарат и мечеть Аль-Хайф."]', 'Остановка по территории. Мина очень большая; эта метка служит центральным ориентиром маршрута, а живой гид должен учитывать текущий лагерь группы, дорогу и схему доступа. В сезон хаджа правила движения могут меняться.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('mina-holy-site', 'uz', 'Mina', 'Masjid al-Haramga eng yaqin asosiy Haj vodiysi va ulkan mavsumiy chodir shaharchasi bilan mashhur hudud.', 'Mina — Masjid al-Haramning sharqidagi vodiyda joylashgan muqaddas Haj hududi. Ziyoratchilar Tarviya kuni bu yerda bo‘ladilar va Tashriq kunlarida yana qaytadilar. Hududda Jamarot majmuasi va Al-Xayf masjidi joylashgan. Haj mavsumida Mina yong‘inga chidamli ulkan chodir infratuzilmasi bilan dunyodagi eng katta vaqtinchalik yashash hududlaridan biriga aylanadi.', '["Mina asosiy Haj hududlari ichida Masjid al-Haramga eng yaqinidir.","U ulkan mavsumiy chodir shaharchasi bilan mashhur.","Jamarot majmuasi va Al-Xayf masjidi Mina hududida joylashgan."]', 'Hudud bo‘ylab to‘xtash. Mina juda katta; bu belgi yo‘nalishning markaziy orientiri, amaliy uchrashuv nuqtasini esa jonli gid guruh lageri, yo‘l va kirish tartibiga qarab belgilaydi. Haj mavsumida harakat qoidalari o‘zgarishi mumkin.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('mina-holy-site', 'uz-cyrl', 'Мина', 'Масжид ал-Ҳарамга энг яқин асосий Ҳаж водийси ва улкан мавсумий чодир шаҳарчаси билан машҳур ҳудуд.', 'Мина — Масжид ал-Ҳарамнинг шарқидаги водийда жойлашган муқаддас Ҳаж ҳудуди. Зиёратчилар Тарвия куни бу ерда бўладилар ва Ташриқ кунларида яна қайтадилар. Ҳудудда Жамарот мажмуаси ва Ал-Хайф масжиди жойлашган. Ҳаж мавсумида Мина ёнғинга чидамли улкан чодир инфратузилмаси билан дунёдаги энг катта вақтинчалик яшаш ҳудудларидан бирига айланади.', '["Мина асосий Ҳаж ҳудудлари ичида Масжид ал-Ҳарамга энг яқинидир.","У улкан мавсумий чодир шаҳарчаси билан машҳур.","Жамарот мажмуаси ва Ал-Хайф масжиди Мина ҳудудида жойлашган."]', 'Ҳудуд бўйлаб тўхташ. Мина жуда катта; бу белги йўналишнинг марказий ориентири, амалий учрашув нуқтасини эса жонли гид гуруҳ лагери, йўл ва кириш тартибига қараб белгилайди. Ҳаж мавсумида ҳаракат қоидалари ўзгариши мумкин.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('mina-holy-site', 'en', 'Mina', 'The major Hajj valley closest to the Grand Mosque, famous for its vast seasonal tent city.', 'Mina is a sacred Hajj site in a valley east of the Grand Mosque. Pilgrims stay here on the Day of Tarwiyah and return during the Days of Tashriq. The area contains the Jamarat Complex and Al-Khayf Mosque and becomes one of the largest temporary accommodation areas in the world during Hajj, with extensive fire-resistant tent infrastructure.', '["Mina is the closest of the main Hajj holy sites to Al-Masjid al-Haram.","It is widely known for its enormous seasonal tent city.","The Jamarat Complex and Al-Khayf Mosque are located within Mina."]', 'Area stop. Mina is very large; this marker is a central route reference, while the live guide should use the group’s current camp, road and access plan. Hajj-season entry and traffic controls can change.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'jamarat-complex', 'makkah-main', 'jamarat-complex', 'Jamarat Complex', 'منشأة الجمرات / جسر الجمرات', 'landmark', 'The multi-level complex in Mina where the three Jamarat are located and the Hajj rite of ramy is performed.', 'The Jamarat Complex in Mina is designed for the Hajj rite of casting pebbles at the three Jamarat: al-Sughra, al-Wusta and al-Kubra, also called al-Aqabah. The modern complex has five levels, multiple entrances and exits, tunnels and cooling systems to manage very large pedestrian flows. The exact map point is placed on the Jamarat Bridge complex rather than on a generic Mina coordinate.', '["The complex contains the three Jamarat: al-Sughra, al-Wusta and al-Kubra/al-Aqabah.","The current Jamarat Complex has five levels.","Its circulation systems are designed to handle very large Hajj pedestrian flows."]', 'Hajj-ritual site. Do not use this card as a substitute for ritual instruction or official crowd-control directions. During Hajj, follow the guide, Nusuk/official scheduling and the designated access route.', 'stop', 30, 21.4213889, 39.8728056, 'Jamarat Complex, Mina, Makkah, Saudi Arabia', 'Jamarat Complex · exact point', 5, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

INSERT OR REPLACE INTO ziyarat_images (id,place_id,object_key,content_type,byte_size,width,height,position,created_at) VALUES
