INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('jamarat-complex', 'ru', 'Комплекс Джамарат', 'Многоуровневый комплекс в Мине, где находятся три Джамарата и совершается обряд рамй во время хаджа.', 'Комплекс Джамарат в Мине предназначен для обряда бросания камешков в три Джамарата: ас-Сугра, аль-Вуста и аль-Кубра, также называемый аль-Акаба. Современный комплекс имеет пять уровней, многочисленные входы и выходы, тоннели и системы охлаждения для управления огромными потоками паломников. Точная метка на карте поставлена на комплекс моста Джамарат, а не на условную точку Мины.', '["Комплекс включает три Джамарата: ас-Сугра, аль-Вуста и аль-Кубра/аль-Акаба.","Современный комплекс Джамарат имеет пять уровней.","Система движения комплекса рассчитана на очень большие потоки паломников во время хаджа."]', 'Место обряда хаджа. Эта карточка не заменяет руководство по манасикам и официальные указания по движению толпы. Во время хаджа следуйте живому гиду, официальному расписанию/Nusuk и назначенному маршруту доступа.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jamarat-complex', 'uz', 'Jamarot majmuasi', 'Minadagi uchta Jamarot joylashgan va Hajda ramy amali bajariladigan ko‘p qavatli majmua.', 'Minadagi Jamarot majmuasi Haj vaqtida uchta Jamarot — as-Sug‘ro, al-Vusto va al-Kubro (al-Aqaba)ga tosh otish amali uchun tashkil etilgan. Zamonaviy majmua besh qavat, ko‘plab kirish-chiqishlar, tunnellar va juda katta piyoda oqimini boshqarishga mo‘ljallangan sovitish tizimlariga ega. Xarita belgisi Minaning umumiy nuqtasiga emas, aynan Jamarot ko‘prigi majmuasiga qo‘yilgan.', '["Majmuada uchta Jamarot bor: as-Sug‘ro, al-Vusto va al-Kubro/al-Aqaba.","Hozirgi Jamarot majmuasi besh qavatdan iborat.","Harakat tizimlari Hajdagi juda katta piyoda oqimini boshqarish uchun loyihalangan."]', 'Haj marosimi joyi. Bu karta manasik bo‘yicha yo‘riqnoma yoki rasmiy odamlar oqimini boshqarish ko‘rsatmalarining o‘rnini bosmaydi. Hajda jonli gid, rasmiy/Nusuk jadvali va belgilangan kirish yo‘liga rioya qiling.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jamarat-complex', 'uz-cyrl', 'Жамарот мажмуаси', 'Минадаги учта Жамарот жойлашган ва Ҳажда рамй амали бажариладиган кўп қаватли мажмуа.', 'Минадаги Жамарот мажмуаси Ҳаж вақтида учта Жамарот — ас-Суғро, ал-Вусто ва ал-Кубро (ал-Ақаба)га тош отиш амали учун ташкил этилган. Замонавий мажмуа беш қават, кўплаб кириш-чиқишлар, туннеллар ва жуда катта пиёда оқимини бошқаришга мўлжалланган совитиш тизимларига эга. Харита белгиси Минанинг умумий нуқтасига эмас, айнан Жамарот кўприги мажмуасига қўйилган.', '["Мажмуада учта Жамарот бор: ас-Суғро, ал-Вусто ва ал-Кубро/ал-Ақаба.","Ҳозирги Жамарот мажмуаси беш қаватдан иборат.","Ҳаракат тизимлари Ҳаждаги жуда катта пиёда оқимини бошқариш учун лойиҳаланган."]', 'Ҳаж маросими жойи. Бу карта манасик бўйича йўриқнома ёки расмий одамлар оқимини бошқариш кўрсатмаларининг ўрнини босмайди. Ҳажда жонли гид, расмий/Nusuk жадвали ва белгиланган кириш йўлига риоя қилинг.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('jamarat-complex', 'en', 'Jamarat Complex', 'The multi-level complex in Mina where the three Jamarat are located and the Hajj rite of ramy is performed.', 'The Jamarat Complex in Mina is designed for the Hajj rite of casting pebbles at the three Jamarat: al-Sughra, al-Wusta and al-Kubra, also called al-Aqabah. The modern complex has five levels, multiple entrances and exits, tunnels and cooling systems to manage very large pedestrian flows. The exact map point is placed on the Jamarat Bridge complex rather than on a generic Mina coordinate.', '["The complex contains the three Jamarat: al-Sughra, al-Wusta and al-Kubra/al-Aqabah.","The current Jamarat Complex has five levels.","Its circulation systems are designed to handle very large Hajj pedestrian flows."]', 'Hajj-ritual site. Do not use this card as a substitute for ritual instruction or official crowd-control directions. During Hajj, follow the guide, Nusuk/official scheduling and the designated access route.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');

INSERT OR REPLACE INTO ziyarat_places (
  id,route_id,slug,title,title_ar,category,short_description,long_description,interesting_facts_json,visit_notes,visit_type,duration_minutes,latitude,longitude,address,map_label,route_order,status,created_by,created_at,updated_at
) VALUES (
  'masjid-al-haram', 'makkah-main', 'masjid-al-haram', 'Al-Masjid al-Haram', 'المسجد الحرام', 'mosque', 'Islam’s holiest mosque in Makkah, surrounding the Kaaba and serving as the central destination of Hajj and Umrah.', 'Al-Masjid al-Haram is the Sacred Mosque of Makkah and surrounds the Kaaba, the qiblah toward which Muslims pray. It is the central destination of Hajj and Umrah and includes the Mataf for tawaf as well as access associated with Zamzam and the Mas‘a between Safa and Marwah. The map point is centered on the Kaaba so the user is taken to the heart of the mosque rather than a random gate or nearby hotel.', '["The Kaaba stands at the center of Al-Masjid al-Haram and is the qiblah for Muslim prayer.","Tawaf is performed around the Kaaba in the Mataf.","The mosque is the central sacred destination for both Hajj and Umrah."]', 'Main sacred stop. Visit time is flexible and may be much longer than the route estimate, especially for prayer, tawaf or Umrah. Entrances, crowd routes and access zones change with prayer times and seasons; follow official directions and the live guide.', 'enter', 90, 21.4225, 39.8261667, 'Al-Masjid al-Haram, Al Haram, Makkah, Saudi Arabia', 'Al-Masjid al-Haram · Kaaba center', 6, 'published', 'seed', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'
);

INSERT OR REPLACE INTO ziyarat_images (id,place_id,object_key,content_type,byte_size,width,height,position,created_at) VALUES
  ('haram-1', 'masjid-al-haram', 'ziyarats/masjid-al-haram/haram-1.jpg', 'image/jpeg', 611107, 1254, 1254, 0, '2026-09-11T16:30:00.000Z'),
  ('haram-2', 'masjid-al-haram', 'ziyarats/masjid-al-haram/haram-2.jpg', 'image/jpeg', 671581, 1254, 1254, 1, '2026-09-11T16:30:00.000Z'),
