INSERT OR REPLACE INTO ziyarat_place_translations (place_id,locale,title,short_description,long_description,interesting_facts_json,visit_notes,created_at,updated_at) VALUES
  ('masjid-al-haram', 'ru', 'Аль-Масджид аль-Харам', 'Главная святыня ислама в Мекке, окружающая Каабу и являющаяся центральным местом хаджа и умры.', 'Аль-Масджид аль-Харам — Заповедная мечеть Мекки, окружающая Каабу, к которой мусульмане обращаются во время намаза. Это центральное место хаджа и умры. В комплекс входит Матaф для тавафа, а также зоны, связанные с Замзамом и Мас‘а между Сафа и Марва. Точка на карте поставлена на центр Каабы, чтобы пользователь попадал к сердцу мечети, а не к случайным воротам или соседнему отелю.', '["Кааба находится в центре Аль-Масджид аль-Харам и является киблой для мусульманского намаза.","Таваф совершается вокруг Каабы в Матaфе.","Мечеть является центральной святыней и для хаджа, и для умры."]', 'Главная священная остановка. Время посещения гибкое и может значительно превышать расчёт маршрута, особенно при намазе, тавафе или умре. Входы и потоки людей меняются в зависимости от времени намаза и сезона; следуйте официальным указаниям и живому гиду.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('masjid-al-haram', 'uz', 'Masjid al-Haram', 'Makkadagi Islomning eng muqaddas masjidi, Ka’bani o‘rab turadi va Haj hamda Umraning markaziy manzilidir.', 'Masjid al-Haram — Makkadagi Muqaddas masjid bo‘lib, musulmonlar namozda yuzlanadigan qibla — Ka’bani o‘rab turadi. U Haj va Umraning markaziy manzilidir. Majmuada Ka’ba atrofidagi Mataf, Zamzam bilan bog‘liq hududlar va Safo-Marva orasidagi Mas’a mavjud. Xarita nuqtasi tasodifiy darvoza yoki yaqin mehmonxonaga emas, aynan Ka’baning markaziga qo‘yilgan.', '["Ka’ba Masjid al-Haram markazida joylashgan va musulmonlar namozining qiblasidir.","Tavof Ka’ba atrofidagi Matafda bajariladi.","Masjid Haj va Umraning markaziy muqaddas manzilidir."]', 'Asosiy muqaddas to‘xtash. Tashrif vaqti erkin bo‘lib, namoz, tavof yoki Umra sabab yo‘nalish hisobidan ancha uzoq davom etishi mumkin. Kirishlar va odamlar oqimi namoz va mavsumga qarab o‘zgaradi; rasmiy ko‘rsatmalar va jonli gidga rioya qiling.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('masjid-al-haram', 'uz-cyrl', 'Масжид ал-Ҳарам', 'Маккадаги Исломнинг энг муқаддас масжиди, Каъбани ўраб туради ва Ҳаж ҳамда Умранинг марказий манзилидир.', 'Масжид ал-Ҳарам — Маккадаги Муқаддас масжид бўлиб, мусулмонлар намозда юзланадиган қибла — Каъбани ўраб туради. У Ҳаж ва Умранинг марказий манзилидир. Мажмуада Каъба атрофидаги Матаф, Замзам билан боғлиқ ҳудудлар ва Сафо-Марва орасидаги Масъа мавжуд. Харита нуқтаси тасодифий дарвоза ёки яқин меҳмонхонага эмас, айнан Каъбанинг марказига қўйилган.', '["Каъба Масжид ал-Ҳарам марказида жойлашган ва мусулмонлар намозининг қибласидир.","Тавоф Каъба атрофидаги Матафда бажарилади.","Масжид Ҳаж ва Умранинг марказий муқаддас манзилидир."]', 'Асосий муқаддас тўхташ. Ташриф вақти эркин бўлиб, намоз, тавоф ёки Умра сабаб йўналиш ҳисобидан анча узоқ давом этиши мумкин. Киришлар ва одамлар оқими намоз ва мавсумга қараб ўзгаради; расмий кўрсатмалар ва жонли гидга риоя қилинг.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z'),
  ('masjid-al-haram', 'en', 'Al-Masjid al-Haram', 'Islam’s holiest mosque in Makkah, surrounding the Kaaba and serving as the central destination of Hajj and Umrah.', 'Al-Masjid al-Haram is the Sacred Mosque of Makkah and surrounds the Kaaba, the qiblah toward which Muslims pray. It is the central destination of Hajj and Umrah and includes the Mataf for tawaf as well as access associated with Zamzam and the Mas‘a between Safa and Marwah. The map point is centered on the Kaaba so the user is taken to the heart of the mosque rather than a random gate or nearby hotel.', '["The Kaaba stands at the center of Al-Masjid al-Haram and is the qiblah for Muslim prayer.","Tawaf is performed around the Kaaba in the Mataf.","The mosque is the central sacred destination for both Hajj and Umrah."]', 'Main sacred stop. Visit time is flexible and may be much longer than the route estimate, especially for prayer, tawaf or Umrah. Entrances, crowd routes and access zones change with prayer times and seasons; follow official directions and the live guide.', '2026-09-11T16:30:00.000Z', '2026-09-11T16:30:00.000Z');
